/// url = 'https://genomde.de/fhir/StructureMap/EngineImportMid'
/// name = 'EngineImportMid'
/// title = 'Engine probe: library that itself imports EngineImportLib (transitive imports)'
/// status = 'draft'

uses "http://hl7.org/fhir/StructureDefinition/Patient" alias Patient as target

imports "https://genomde.de/fhir/StructureMap/EngineImportLib"

group MidPatient(source md, target pat : Patient) {
  md then LibPatient(md, pat) "via-lib";
  md.gender as g -> pat.gender = g "mid";
}
